fn grants()->serde_json::Value{serde_json::from_str(fixture_text!("../../../🚪️io/🪶️sqlite/📸️snapshot/🫴️receiving/🧪️tests/🧫️fixtures/🎟️grants.json")).unwrap()}
fn grant(value:&serde_json::Value)->RetainedCloneGrant{serde_json::from_value(value.clone()).unwrap()}
fn scalar(value:&serde_json::Value)->semio_framework_os_kernel::sqlite_snapshot::SqliteValue{use semio_framework_os_kernel::sqlite_snapshot::SqliteValue as V;match value{serde_json::Value::Null=>V::Null,serde_json::Value::String(v)=>V::Text(v.clone()),serde_json::Value::Number(v)=>V::Real(v.as_f64().unwrap()),_=>V::Integer(value["integer"].as_str().unwrap().parse().unwrap())}}
fn input(empty:bool)->SqliteDatabase{use semio_framework_os_kernel::sqlite_snapshot::SqliteTable;let input:serde_json::Value=serde_json::from_str(if empty{fixture_text!("../../../🚪️io/🪶️sqlite/📸️snapshot/🫴️receiving/🧪️tests/🧫️fixtures/∅️input.json")}else{fixture_text!("../../../🚪️io/🪶️sqlite/📸️snapshot/🫴️receiving/🧪️tests/🧫️fixtures/🏛️input.json")}).unwrap();SqliteDatabase{tables:input["tables"].as_array().unwrap().iter().map(|table|SqliteTable{name:table["name"].as_str().unwrap().into(),sql:table["sql"].as_str().unwrap().into(),rows:table["rows"].as_array().unwrap().iter().map(|row|SqliteRow{rowid:row["rowid"].as_str().unwrap().parse().unwrap(),values:row["values"].as_array().unwrap().iter().map(scalar).collect()}).collect()}).collect()}}
fn close<T:semio_framework_value::retirement::RetireOwned>(original:T,policy:RetainedCloneGrant)->(usize,usize){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(original).ok().unwrap();let(mut born,mut freed)=(0,0);for _ in 0..4096{if owner.terminal_is_empty(){break}let(step,heap)=observe(||owner.step(policy).unwrap());assert!(step.progress().fits(policy));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;}assert!(owner.terminal_is_empty());(born,freed)}
macro_rules! original{
 ($name:ident,$native:ident,$owner:ident,$recipient:path,$output:ty)=>{
  fn $name(policy:RetainedCloneGrant,callback:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool,operation:impl FnOnce(&mut SqliteSnapshotControl<'_>,&mut store::$owner<'_,'_>)->Result<$output,ValueError>)->(Result<$output,ValueError>,RetainedCloneProgress,usize,usize){
   let laws=grants();let denied=grant(&laws["denied"]);let closing=grant(&laws["close"]);let mut observer=|_|true;let mut recipient=<$recipient>::new();let mut native=$native::new(16777216,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut sql=SqliteSnapshotControl::new(callback,Default::default());let before=sql.allocation_remaining_bytes();let mut owner=store::$owner::new(&mut native,policy);let(result,heap)=observe(||operation(&mut sql,&mut owner));let receipt=owner.progress();assert!(receipt.fits(policy));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));if let Err(error)=&result{assert_eq!(error.retained_progress(),receipt)}drop(owner);assert_eq!(before-sql.allocation_remaining_bytes(),native.owned_bytes());let(mut born,mut freed)=(heap.requested_bytes,heap.released_bytes);
   let(zero,heap)=observe(||native.close_retirement_recipient(denied).unwrap());assert_eq!(zero.progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for _ in 0..4096{if !native.has_retirement_owner(){break}let(step,heap)=observe(||native.close_retirement_recipient(closing).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;}assert!(!native.has_retirement_owner());(result,receipt,born,freed)
  }
 };
}
original!(decode,NativeDecodeControl,NativeSnapshotDecodeOwner,semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient,SqliteDatabase);
original!(encode,NativeEncodeControl,NativeSnapshotEncodeOwner,semio_framework_value::native_encoding::NativeEncodeRetirementRecipient,StlSnapshot);
#[test]
fn stl_original_receiving_complete_fixed_scalars_and_indexes_conserve_actual_original_backing(){
 let law=grants();let incoming=grant(&law["body"]);let closing=grant(&law["close"]);
 for empty in [false,true]{let original=input(empty);let pointer=original.tables.as_ptr();let(restored,_,born,freed)=encode(incoming,&mut |_|true,|sql,owner|StlSnapshot::from_sqlite_database_receiving(&original,sql,owner));let restored=restored.unwrap();assert_eq!(restored.schema,"literal/schema λ\0");assert_eq!(restored.solid_name,"Original 世界\0 name");assert_eq!(restored.triangles.len(),if empty{0}else{2});if !empty{assert_eq!(restored.triangles[0].normal.map(f64::to_bits),[0x8000000000000000,0x7ff8123456789abc,0]);}assert_eq!(pointer,original.tables.as_ptr());let(projected,_,pborn,pfreed)=decode(incoming,&mut |_|true,|sql,owner|restored.to_sqlite_database_receiving(sql,owner));let projected=projected.unwrap();assert_eq!(projected.tables.len(),3);assert_eq!(projected.tables[1].rows.len(),restored.triangles.len());assert_eq!(projected.tables[2].rows.len(),restored.triangles.len()*3);let(a,b)=close(restored,closing);assert_eq!(born+a,freed+b);let(a,b)=close(projected,closing);assert_eq!(pborn+a,pfreed+b);}
}
#[test]
fn stl_original_receiving_denied_axes_and_malformed_rows_retain_original_custody(){
 let law=grants();let incoming=grant(&law["body"]);let source=StlSnapshot{schema:"original".into(),solid_name:"name".into(),triangles:vec![StlTriangle::default()]};let original=input(false);
 for axis in ["items","copy","capacity","release","depth"]{let mut policy=incoming;match axis{"items"=>policy.maximum_items=0,"copy"=>policy.maximum_copy_bytes=0,"capacity"=>policy.maximum_capacity_bytes=0,"release"=>policy.maximum_release_bytes=0,_=>policy.maximum_depth=0};let(result,_,born,freed)=decode(policy,&mut |_|true,|sql,owner|source.to_sqlite_database_receiving(sql,owner));assert!(result.is_err(),"{axis}");assert_eq!(born,freed);if ["items","capacity","depth"].contains(&axis){assert_eq!(born,0)}let(result,_,born,freed)=encode(policy,&mut |_|true,|sql,owner|StlSnapshot::from_sqlite_database_receiving(&original,sql,owner));assert!(result.is_err(),"{axis}");assert_eq!(born,freed);if ["items","capacity","depth"].contains(&axis){assert_eq!(born,0)}}
 let cases:serde_json::Value=serde_json::from_str(fixture_text!("../../../🚪️io/🪶️sqlite/📸️snapshot/🫴️receiving/🧪️tests/🧫️fixtures/⚠️malformed.json")).unwrap();for case in cases.as_array().unwrap(){let mut original=input(false);let table=original.tables.iter_mut().find(|t|t.name==case["table"].as_str().unwrap()).unwrap();let index=case["row"].as_u64().unwrap()as usize;if case["remove"]==true{table.rows.remove(index);}else if case["duplicate"]==true{table.rows.push(table.rows[index].clone());}else{table.rows[index].values[case["column"].as_u64().unwrap()as usize]=scalar(&case["value"]);}let pointer=original.tables.as_ptr();let(result,_,born,freed)=encode(incoming,&mut |_|true,|sql,owner|StlSnapshot::from_sqlite_database_receiving(&original,sql,owner));let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue,"{}",case["id"]);assert!(matches!(error.message,std::borrow::Cow::Borrowed(_)));assert_eq!(born,freed);assert_eq!(pointer,original.tables.as_ptr());}
}

#[test]
fn stl_original_receiving_sql_cancellation_retains_exact_cause_and_same_original_close_observer(){
 use std::cell::Cell;let law=grants();let incoming=grant(&law["body"]);let denied=grant(&law["denied"]);let closing=grant(&law["close"]);let long="世界\0".repeat(32768);let bytes=long.len();let source=StlSnapshot{schema:"original".into(),solid_name:long.clone(),triangles:vec![StlTriangle::default()]};let mut input=input(false);input.tables[0].rows[0].values[2]=semio_framework_os_kernel::sqlite_snapshot::SqliteValue::Text(long);
 macro_rules! direction{
  ($native:ident,$owner:ident,$recipient:path,$call:expr)=>{{
   let blocked=Cell::new(false);let canceled=Cell::new(false);let mut callback=|_|!blocked.get();let mut recipient=<$recipient>::new();let mut native=$native::new(16777216,&mut callback);native.install_retirement_recipient(&mut recipient).unwrap();let mut sql_callback=|event:semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress|{let cut=event.total==bytes&&event.completed>=65536&&event.completed<event.total;canceled.set(canceled.get()||cut);!cut};let mut sql=SqliteSnapshotControl::new(&mut sql_callback,Default::default());let before=sql.allocation_remaining_bytes();let mut owner=store::$owner::new(&mut native,incoming);let(result,heap)=observe(||($call)(&mut sql,&mut owner));let receipt=owner.progress();let error=result.unwrap_err();assert!(canceled.get());assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.message,"relational SQLite transfer cancelled");assert!(matches!(error.message,std::borrow::Cow::Borrowed(_)));assert_eq!(error.retained_progress(),receipt);assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));drop(owner);assert_eq!(before-sql.allocation_remaining_bytes(),native.owned_bytes());assert!(native.has_retirement_owner());let(mut born,mut freed)=(heap.requested_bytes,heap.released_bytes);let(step,heap)=observe(||native.close_retirement_recipient(denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));blocked.set(true);let(step,heap)=observe(||native.close_retirement_recipient(closing));assert_eq!(step.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(native.has_retirement_owner());blocked.set(false);for _ in 0..4096{if !native.has_retirement_owner(){break}let(step,heap)=observe(||native.close_retirement_recipient(closing).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;}assert!(!native.has_retirement_owner());assert_eq!(born,freed);
  }};
 }
 direction!(NativeDecodeControl,NativeSnapshotDecodeOwner,semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient,|sql:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotDecodeOwner<'_,'_>|source.to_sqlite_database_receiving(sql,owner));
 direction!(NativeEncodeControl,NativeSnapshotEncodeOwner,semio_framework_value::native_encoding::NativeEncodeRetirementRecipient,|sql:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotEncodeOwner<'_,'_>|StlSnapshot::from_sqlite_database_receiving(&input,sql,owner));
}
