#[test]
fn stl_original_receiving_directional_validation_preserves_exact_dialect_and_document_policy(){
 let law=grants();let incoming=grant(&law["body"]);let input=input(false);let source=StlSnapshot{schema:"literal/schema λ\0".into(),solid_name:"Original 世界\0 name".into(),triangles:vec![StlTriangle{normal:[f64::from_bits(0x8000000000000000),f64::from_bits(0x7ff8123456789abc),0.0],vertices:[[0.0;3];3]},StlTriangle{normal:[1.25,0.0,0.0],vertices:[[0.0;3];3]}]};
 for(kind,standard,subset,accepted)in[("s.stdio.stl","ascii","*",true),("s.stdio.binary","ascii","*",false),("s.stdio.stl","unknown","*",false),("s.stdio.stl","ascii","unknown",false)]{let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:kind.into(),standard:standard.into(),subset:subset.into()};let(result,_,born,freed)=validate_decode(incoming,&mut |_|true,|sql,owner|source.validate_sqlite_snapshot_subset_decoding(&dialect,&input,sql,owner).map(|_|()).map_err(|error|error.cause));assert_eq!(result.is_ok(),accepted);assert_eq!(born,freed);if !accepted{assert_eq!(born,0);let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!(error.message,"geometry owned SQLite dialect differs");}let(result,_,born,freed)=validate_encode(incoming,&mut |_|true,|sql,owner|source.validate_sqlite_snapshot_subset_encoding(&dialect,&input,sql,owner).map(|_|()).map_err(|error|error.cause));assert_eq!(result.is_ok(),accepted);assert_eq!(born,freed);}
 let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.stl".into(),standard:"ascii".into(),subset:"*".into()};let mut changed=input.clone();changed.tables[0].rows[0].values[1]=semio_framework_os_kernel::sqlite_snapshot::SqliteValue::Text("different".into());let(result,_,born,freed)=validate_decode(incoming,&mut |_|true,|sql,owner|source.validate_sqlite_snapshot_subset_decoding(&dialect,&changed,sql,owner).map(|_|()).map_err(|error|error.cause));assert_eq!(result.unwrap_err().message,"STL document identity differs from its semantic projection");assert_eq!(born,freed);
}

#[test]
fn stl_original_receiving_original_native_and_sql_capacity_ceilings_refuse_before_birth(){
 let law=grants();let policy=grant(&law["body"]);let original=input(false);let source=StlSnapshot{schema:"original".into(),solid_name:"name".into(),triangles:vec![StlTriangle::default()]};
 macro_rules! direction{($native:ident,$owner:ident,$recipient:path,$call:expr)=>{{for(native_maximum,sql_maximum)in[(0,16777216),(16777216,0)]{let mut callback=|_|true;let mut recipient=<$recipient>::new();let mut native=$native::new(native_maximum,&mut callback);native.install_retirement_recipient(&mut recipient).unwrap();let mut sql=SqliteSnapshotControl::new(&mut |_|true,semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_allocation_bytes:sql_maximum,..Default::default()});let mut owner=store::$owner::new(&mut native,policy);let(result,heap)=observe(||($call)(&mut sql,&mut owner));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(owner.progress(),RetainedCloneProgress::default());drop(owner);assert_eq!(native.owned_bytes(),0);assert!(!native.has_retirement_owner());}}};}
 direction!(NativeDecodeControl,NativeSnapshotDecodeOwner,semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient,|sql:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotDecodeOwner<'_,'_>|source.to_sqlite_database_receiving(sql,owner));
 direction!(NativeEncodeControl,NativeSnapshotEncodeOwner,semio_framework_value::native_encoding::NativeEncodeRetirementRecipient,|sql:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotEncodeOwner<'_,'_>|StlSnapshot::from_sqlite_database_receiving(&original,sql,owner));
}
#[test]
fn stl_original_receiving_long_original_index_cancels_with_paid_partial_scratch(){
 let law=grants();let mut original=input(false);let facet=original.tables[1].rows[0].clone();let vertices=original.tables[2].rows[..3].to_vec();original.tables[1].rows.clear();original.tables[2].rows.clear();for ordinal in (0..2048i64).rev(){let id=ordinal+1;let mut row=facet.clone();row.rowid=id;row.values[0]=semio_framework_os_kernel::sqlite_snapshot::SqliteValue::Integer(id);row.values[2]=semio_framework_os_kernel::sqlite_snapshot::SqliteValue::Integer(ordinal);original.tables[1].rows.push(row);for position in 0..3{let mut row=vertices[position].clone();row.rowid=ordinal*3+position as i64+1;row.values[0]=semio_framework_os_kernel::sqlite_snapshot::SqliteValue::Integer(row.rowid);row.values[1]=semio_framework_os_kernel::sqlite_snapshot::SqliteValue::Integer(id);row.values[2]=semio_framework_os_kernel::sqlite_snapshot::SqliteValue::Integer(position as i64);original.tables[2].rows.push(row);}}
 let pointer=original.tables.as_ptr();let mut calls=0;let mut canceled=false;let(result,receipt,born,freed)=encode(grant(&law["body"]),&mut |event|{if event.phase==SqliteSnapshotPhase::ReconstructSnapshot{calls+=1;if calls>=40000{canceled=true;return false}}true},|sql,owner|StlSnapshot::from_sqlite_database_receiving(&original,sql,owner));let error=result.unwrap_err();assert!(canceled);assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.message,"relational SQLite transfer cancelled");assert_eq!(born,freed);assert!(receipt.retained_capacity_bytes>0);assert_eq!(pointer,original.tables.as_ptr());
}

#[semio_framework_async_macros::async_test]
async fn stl_original_receiving_whole_typed_file_uses_original_semantic_owner_and_policy(){
 use semio_framework_os_kernel::{io::{testing::{SnapshotFileCaller,with_snapshot_file_decoding,with_snapshot_file_encoding},io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}},sqlite_snapshot::SnapshotEncoding};
 semio_framework_plugin::PluginBuilder::<_, semio_framework_plugin::app::NoPluginApp>::new("stdio").label("STL original receiving file law").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();
 let law=grants();let policy=SnapshotFileCaller{grant:grant(&law["body"]),native_maximum_bytes:16777216,close_grant:grant(&law["close"]),maximum_close_turns:4096};let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.stl".into(),standard:"ascii".into(),subset:"*".into()};let source=StlSnapshot{schema:"literal/schema λ\0".into(),solid_name:"Original 世界\0 name".into(),triangles:vec![StlTriangle{normal:[f64::from_bits(0x8000000000000000),f64::from_bits(0x7ff8123456789abc),0.0],vertices:[[0.0;3];3]},StlTriangle{normal:[1.25,0.0,0.0],vertices:[[0.0;3];3]}]};let pointer=source.schema.as_ptr();let mut native_phase=false;
 for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut callback=|event:semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress|{native_phase|=matches!(event.phase,SqliteSnapshotPhase::DecodeNative|SqliteSnapshotPhase::EncodeNative);true};let file=with_snapshot_file_decoding(policy,Default::default(),&mut callback,async|sql,owner|io_export_sqlite_snapshot(&dialect,&source,encoding,sql,owner).await).await.unwrap();assert!(file.diagnostics.is_empty());assert!(file.value.starts_with(b"SQLite format 3\0"));let restored=with_snapshot_file_encoding(policy,Default::default(),&mut callback,async|sql,owner|io_import_sqlite_snapshot::<StlSnapshot>(&dialect,&file.value,sql,owner).await).await.unwrap();assert!(restored.diagnostics.is_empty());assert_eq!((&restored.value.schema,&restored.value.solid_name),(&source.schema,&source.solid_name));assert_eq!(restored.value.triangles.len(),source.triangles.len());for(actual,expected)in restored.value.triangles.iter().zip(&source.triangles){assert_eq!(actual.normal.map(f64::to_bits),expected.normal.map(f64::to_bits));assert_eq!(actual.vertices.map(|point|point.map(f64::to_bits)),expected.vertices.map(|point|point.map(f64::to_bits)));}let _=close(restored.value,policy.close_grant);let _=close(file.value,policy.close_grant);}
 assert!(!native_phase);assert_eq!(pointer,source.schema.as_ptr());
}
